function LAWVERE_FIXED_POINT(e, A, f):
    # e : A -> (A -> B) surjective; f : B -> B
    d <- new function on A
    for x in A:
        d[x] <- f(e[x][x])          # diagonalise then post-compose
    for a in A:
        if e[a] == d:               # a names the diagonal (surjectivity)
            return e[a][a]          # y with f(y) = y
    error "e not surjective"

