function DIAGONAL_WITNESS(e, A, flip):
    # flip : B -> B fixed-point-free (e.g. NOT)
    d <- new function on A
    for x in A:
        d[x] <- flip(e[x][x])       # the escaping diagonal
    return d                        # d != e[a] at x=a, for every a

function TRILEMMA_SEARCH(pairs):
    build neg[] from pairs; sentences <- keys(neg)
    violations <- 0
    for each subset Prov of sentences:
        consistent <- for all s: not (s in Prov and neg[s] in Prov)
        complete   <- for all s: s in Prov or neg[s] in Prov
        diagonal   <- exists g: (g in Prov) == (neg[g] in Prov)
        if consistent and complete and diagonal:
            violations <- violations + 1
    return violations           # always 0, by Theorem 5

function REFLECTION_TOWER(levels):
    tower <- [ empty_set ]
    for n in 0 .. levels-1:
        tower.append( tower[last] union { n } )   # add Con(F_n)
    return tower
function ESCAPES_UNION(tower):
    U <- union of all sets in tower
    return max(U) + 1            # fresh diagonal beyond every level
